window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e22af536a42008d1"]={"versions": [{"id": "FIG-e22af536a42008d1", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Veranschaulichung der AUTOSAR-XML-Persistenzregeln (Order of XML elements). Es definiert die Metamodell-Vererbungshierarchie und Kompositionsstrukturen am Beispiel von <code>AtomicSoftwareComponentType</code> und demonstriert die Determinierung der Serialisierungsreihenfolge von XML-Elementen basierend auf Metaklassen-Vererbung und <code>sequenceOffset</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellte Metaklassen und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Identifiable</code> («atpIdentifiable», {abstract}): Basisklasse mit Attributen <code>shortName: Identifier</code>, <code>longName: String [0..1]</code>, <code>category: String [0..1]</code>, <code>uuid: String [0..1]</code>, <code>checksum: String [0..1]</code> und <code>timestamp: DateTime [0..1]</code>. Links sind Werte für <code>sequenceOffset</code> annotiert (<code>-100</code>, <code>-120</code>, <code>0</code>, <code>0</code>, <code>0</code>, <code>0</code>).</li>\n<li><code>PropertyEvaluator</code> ({abstract}) und <code>PropertyContainer</code> ({abstract}): Abstrakte Klassen in der Vererbungshierarchie.</li>\n<li><code>ARElement</code> («atpIdentifiable», {abstract}): Erbt per Mehrfachvererbung von <code>PropertyEvaluator</code>, <code>Identifiable</code> und <code>PropertyContainer</code>.</li>\n<li><code>ComponentType</code> ({abstract}): Erbt von <code>ARElement</code>. Besitzt eine Kompositionsbeziehung zu <code>PortPrototype</code> ({abstract}) mit Multiplizität <code>0..*</code> und Rollenbezeichnungen <code>+component</code> / <code>+ports</code>.</li>\n<li><code>AtomicSoftwareComponentType</code>: Konkrete Spezialisierung von <code>ComponentType</code>.</li>\n<li><code>PropertyPrototype</code>: Kompositionselement von <code>PropertyContainer</code> mit Multiplizität <code>0..*</code> und Rollenbezeichnung <code>+properties</code>; Attribute: <code>type: Enumeration{Int, Float, Boolean}</code> und <code>defaultValue: String [0..1]</code>.</li>\n</ul>\n<p class=\"fig-p\">Die durchnummerierten Dokumentensymbole (1 bis 6) kennzeichnen die Auswertungs- bzw. Vererbungsreihenfolge für die XML-Serialisierung.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Laufzeit-Sequenzen. Die durchnummerierten Notizzettel (1 bis 6) illustrieren die semantische Sequenzabfolge bei der XML-Generierung: Beginnend bei den generalisierten Basisklassen (<code>Identifiable</code> [1], <code>PropertyContainer</code> [2], <code>PropertyEvaluator</code> [3]) über <code>ARElement</code> [4] und <code>ComponentType</code> [5] hin zu <code>AtomicSoftwareComponentType</code> [6]. Innerhalb der Attribute von <code>Identifiable</code> bestimmt der <code>sequenceOffset</code> die relative Vorrangfolge (z. B. negative Offsets wie <code>-120</code> und <code>-100</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Metamodell-Schema für AUTOSAR-XML-Serialisierer und -Parser gemäß TR XML Persistence Rules. Entwickler von Modellierungs- und Generierungswerkzeugen müssen sicherstellen, dass Kindelemente und Attribute in der durch die Vererbungshierarchie und <code>sequenceOffset</code>-Tags vorgegebenen Reihenfolge im XML-Dokument serialisiert werden, um Schema-Konformität und deterministische XML-Artefakte zu garantieren.</p>"}, {"id": "FIG-cf04eb51e584e9a9", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Veranschaulichung der AUTOSAR-XML-Persistenzregeln (Order of XML elements). Es definiert die Metamodell-Vererbungshierarchie und Kompositionsstrukturen am Beispiel von <code>AtomicSoftwareComponentType</code> und demonstriert die Determinierung der Serialisierungsreihenfolge von XML-Elementen basierend auf Metaklassen-Vererbung und <code>sequenceOffset</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellte Metaklassen und deren Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Identifiable</code> («atpIdentifiable», {abstract}): Basisklasse mit Attributen <code>shortName: Identifier</code>, <code>longName: String [0..1]</code>, <code>category: String [0..1]</code>, <code>uuid: String [0..1]</code>, <code>checksum: String [0..1]</code> und <code>timestamp: DateTime [0..1]</code>. Links sind Werte für <code>sequenceOffset</code> annotiert (<code>-100</code>, <code>-120</code>, <code>0</code>, <code>0</code>, <code>0</code>, <code>0</code>).</li>\n<li><code>PropertyEvaluator</code> ({abstract}) und <code>PropertyContainer</code> ({abstract}): Abstrakte Klassen in der Vererbungshierarchie.</li>\n<li><code>ARElement</code> («atpIdentifiable», {abstract}): Erbt per Mehrfachvererbung von <code>PropertyEvaluator</code>, <code>Identifiable</code> und <code>PropertyContainer</code>.</li>\n<li><code>ComponentType</code> ({abstract}): Erbt von <code>ARElement</code>. Besitzt eine Kompositionsbeziehung zu <code>PortPrototype</code> ({abstract}) mit Multiplizität <code>0..*</code> und Rollenbezeichnungen <code>+component</code> / <code>+ports</code>.</li>\n<li><code>AtomicSoftwareComponentType</code>: Konkrete Spezialisierung von <code>ComponentType</code>.</li>\n<li><code>PropertyPrototype</code>: Kompositionselement von <code>PropertyContainer</code> mit Multiplizität <code>0..*</code> und Rollenbezeichnung <code>+properties</code>; Attribute: <code>type: Enumeration{Int, Float, Boolean}</code> und <code>defaultValue: String [0..1]</code>.</li>\n</ul>\n<p class=\"fig-p\">Die durchnummerierten Dokumentensymbole (1 bis 6) kennzeichnen die Auswertungs- bzw. Vererbungsreihenfolge für die XML-Serialisierung.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Laufzeit-Sequenzen. Die durchnummerierten Notizzettel (1 bis 6) illustrieren die semantische Sequenzabfolge bei der XML-Generierung: Beginnend bei den generalisierten Basisklassen (<code>Identifiable</code> [1], <code>PropertyContainer</code> [2], <code>PropertyEvaluator</code> [3]) über <code>ARElement</code> [4] und <code>ComponentType</code> [5] hin zu <code>AtomicSoftwareComponentType</code> [6]. Innerhalb der Attribute von <code>Identifiable</code> bestimmt der <code>sequenceOffset</code> die relative Vorrangfolge (z. B. negative Offsets wie <code>-120</code> und <code>-100</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normatives Metamodell-Schema für AUTOSAR-XML-Serialisierer und -Parser gemäß TR XML Persistence Rules. Entwickler von Modellierungs- und Generierungswerkzeugen müssen sicherstellen, dass Kindelemente und Attribute in der durch die Vererbungshierarchie und <code>sequenceOffset</code>-Tags vorgegebenen Reihenfolge im XML-Dokument serialisiert werden, um Schema-Konformität und deterministische XML-Artefakte zu garantieren.</p>"}], "trans": [{"from": "FIG-e22af536a42008d1", "to": "FIG-cf04eb51e584e9a9", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
